ALTER TABLE "Branch" ADD COLUMN "schedule" JSONB NOT NULL DEFAULT '[]', ADD COLUMN "holidays" JSONB NOT NULL DEFAULT '{}', ADD COLUMN "preparationMinutes" INTEGER NOT NULL DEFAULT 30 CHECK ("preparationMinutes" BETWEEN 1 AND 180), ADD COLUMN "maxActiveOrders" INTEGER NOT NULL DEFAULT 100 CHECK ("maxActiveOrders">0), ADD COLUMN "allowCash" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "minimumPickupMinor" INTEGER NOT NULL DEFAULT 0 CHECK ("minimumPickupMinor">=0);
ALTER TABLE "Product" ADD COLUMN "stockQuantity" INTEGER CHECK ("stockQuantity">=0);
ALTER TABLE "RoleBinding" ADD COLUMN "refundAllowed" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE "DeliveryZone" ("id" UUID PRIMARY KEY,"branchId" UUID NOT NULL REFERENCES "Branch"("id") ON DELETE RESTRICT,"name" TEXT NOT NULL,"polygon" JSONB NOT NULL,"priority" INTEGER NOT NULL DEFAULT 0,"feeMinor" INTEGER NOT NULL CHECK ("feeMinor">=0),"minimumMinor" INTEGER NOT NULL DEFAULT 0 CHECK ("minimumMinor">=0),"freeThresholdMinor" INTEGER CHECK ("freeThresholdMinor">=0),"active" BOOLEAN NOT NULL DEFAULT true,"version" INTEGER NOT NULL DEFAULT 1);
CREATE INDEX "DeliveryZone_branchId_active_priority_idx" ON "DeliveryZone"("branchId","active","priority");
CREATE TABLE "Promotion" ("id" UUID PRIMARY KEY,"branchId" UUID NOT NULL REFERENCES "Branch"("id") ON DELETE RESTRICT,"code" TEXT NOT NULL,"basisPoints" INTEGER CHECK ("basisPoints" BETWEEN 1 AND 10000),"fixedMinor" INTEGER CHECK ("fixedMinor">0),"maxDiscountMinor" INTEGER CHECK ("maxDiscountMinor">0),"minimumMinor" INTEGER NOT NULL DEFAULT 0 CHECK ("minimumMinor">=0),"totalLimit" INTEGER CHECK ("totalLimit">0),"customerLimit" INTEGER CHECK ("customerLimit">0),"startsAt" TIMESTAMPTZ(3) NOT NULL,"endsAt" TIMESTAMPTZ(3) NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"version" INTEGER NOT NULL DEFAULT 1, CHECK (("basisPoints" IS NULL) <> ("fixedMinor" IS NULL)), CHECK ("endsAt">"startsAt"));
CREATE UNIQUE INDEX "Promotion_branchId_code_key" ON "Promotion"("branchId","code");
CREATE TABLE "Quote" ("id" UUID PRIMARY KEY,"customerId" UUID NOT NULL REFERENCES "Customer"("id") ON DELETE RESTRICT,"branchId" UUID NOT NULL REFERENCES "Branch"("id") ON DELETE RESTRICT,"input" JSONB NOT NULL,"calculation" JSONB NOT NULL,"signature" TEXT NOT NULL,"expiresAt" TIMESTAMPTZ(3) NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Quote_customerId_createdAt_idx" ON "Quote"("customerId","createdAt");
CREATE TYPE "OrderStatus" AS ENUM ('awaiting_payment','placed','accepted','preparing','ready','out_for_delivery','delivered','completed','rejected','cancelled','expired');
CREATE TYPE "PaymentStatus" AS ENUM ('unpaid','pending','paid','failed','expired','refund_pending','refunded','manual_review');
CREATE TABLE "Order" ("id" UUID PRIMARY KEY,"quoteId" UUID NOT NULL UNIQUE REFERENCES "Quote"("id") ON DELETE RESTRICT,"customerId" UUID NOT NULL REFERENCES "Customer"("id") ON DELETE RESTRICT,"branchId" UUID NOT NULL REFERENCES "Branch"("id") ON DELETE RESTRICT,"fulfilment" TEXT NOT NULL CHECK ("fulfilment" IN ('pickup','delivery')),"addressSnapshot" JSONB,"comment" TEXT NOT NULL DEFAULT '',"status" "OrderStatus" NOT NULL,"paymentMethod" TEXT NOT NULL CHECK ("paymentMethod" IN ('mock','cash')),"paymentStatus" "PaymentStatus" NOT NULL,"currency" TEXT NOT NULL DEFAULT 'KZT' CHECK ("currency"='KZT'),"subtotalMinor" INTEGER NOT NULL CHECK ("subtotalMinor">=0),"discountMinor" INTEGER NOT NULL CHECK ("discountMinor">=0),"deliveryFeeMinor" INTEGER NOT NULL CHECK ("deliveryFeeMinor">=0),"totalMinor" INTEGER NOT NULL CHECK ("totalMinor">0),"pickupSecret" TEXT,"version" INTEGER NOT NULL DEFAULT 1,"expiresAt" TIMESTAMPTZ(3) NOT NULL,"preparationMinutes" INTEGER,"courierId" UUID REFERENCES "StaffUser"("id") ON DELETE RESTRICT,"courierAccepted" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL, CHECK ("totalMinor"="subtotalMinor"-"discountMinor"+"deliveryFeeMinor"));
CREATE INDEX "Order_branchId_status_createdAt_idx" ON "Order"("branchId","status","createdAt");
CREATE INDEX "Order_customerId_createdAt_idx" ON "Order"("customerId","createdAt");
CREATE INDEX "Order_courierId_status_idx" ON "Order"("courierId","status");
CREATE TABLE "OrderItem" ("id" UUID PRIMARY KEY,"orderId" UUID NOT NULL REFERENCES "Order"("id") ON DELETE RESTRICT,"productId" UUID NOT NULL,"nameRu" TEXT NOT NULL,"nameKk" TEXT NOT NULL,"quantity" INTEGER NOT NULL CHECK ("quantity" BETWEEN 1 AND 99),"unitPriceMinor" INTEGER NOT NULL CHECK ("unitPriceMinor">0),"lineTotalMinor" INTEGER NOT NULL CHECK ("lineTotalMinor"="unitPriceMinor"*"quantity"));
CREATE TABLE "StockReservation" ("orderId" UUID NOT NULL REFERENCES "Order"("id") ON DELETE RESTRICT,"productId" UUID NOT NULL REFERENCES "Product"("id") ON DELETE RESTRICT,"quantity" INTEGER NOT NULL CHECK ("quantity">0),"releasedAt" TIMESTAMPTZ(3), PRIMARY KEY ("orderId","productId"));
CREATE TABLE "PromotionRedemption" ("id" UUID PRIMARY KEY,"promotionId" UUID NOT NULL REFERENCES "Promotion"("id") ON DELETE RESTRICT,"customerId" UUID NOT NULL REFERENCES "Customer"("id") ON DELETE RESTRICT,"orderId" UUID NOT NULL UNIQUE REFERENCES "Order"("id") ON DELETE RESTRICT,"releasedAt" TIMESTAMPTZ(3));
CREATE INDEX "PromotionRedemption_promotionId_customerId_releasedAt_idx" ON "PromotionRedemption"("promotionId","customerId","releasedAt");
CREATE TABLE "PaymentAttempt" ("id" UUID PRIMARY KEY,"orderId" UUID NOT NULL REFERENCES "Order"("id") ON DELETE RESTRICT,"provider" TEXT NOT NULL DEFAULT 'mock',"providerId" TEXT NOT NULL UNIQUE,"amountMinor" INTEGER NOT NULL CHECK ("amountMinor">0),"status" "PaymentStatus" NOT NULL DEFAULT 'pending',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "PaymentAttempt_orderId_idx" ON "PaymentAttempt"("orderId");
CREATE TABLE "Refund" ("id" UUID PRIMARY KEY,"paymentId" UUID NOT NULL UNIQUE REFERENCES "PaymentAttempt"("id") ON DELETE RESTRICT,"amountMinor" INTEGER NOT NULL CHECK ("amountMinor">0),"reason" TEXT NOT NULL,"status" TEXT NOT NULL,"provider" TEXT NOT NULL DEFAULT 'mock',"confirmedAt" TIMESTAMPTZ(3),"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "OrderEvent" ("id" UUID PRIMARY KEY,"orderId" UUID NOT NULL REFERENCES "Order"("id") ON DELETE RESTRICT,"actorId" UUID,"action" TEXT NOT NULL,"version" INTEGER NOT NULL,"reason" TEXT,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "OrderEvent_orderId_createdAt_idx" ON "OrderEvent"("orderId","createdAt");
CREATE TABLE "IdempotencyRecord" ("actorId" UUID NOT NULL,"scope" TEXT NOT NULL,"key" TEXT NOT NULL,"requestHash" TEXT NOT NULL,"response" JSONB NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("actorId","scope","key"));
CREATE TABLE "OutboxEvent" ("id" UUID PRIMARY KEY,"aggregateId" UUID NOT NULL,"version" INTEGER NOT NULL,"type" TEXT NOT NULL,"payload" JSONB NOT NULL,"processedAt" TIMESTAMPTZ(3),"attempts" INTEGER NOT NULL DEFAULT 0,"nextAttemptAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "OutboxEvent_processedAt_nextAttemptAt_idx" ON "OutboxEvent"("processedAt","nextAttemptAt");
CREATE TABLE "Notification" ("id" UUID PRIMARY KEY,"eventId" UUID NOT NULL UNIQUE REFERENCES "OutboxEvent"("id") ON DELETE RESTRICT,"customerId" UUID NOT NULL REFERENCES "Customer"("id") ON DELETE RESTRICT,"orderId" UUID NOT NULL REFERENCES "Order"("id") ON DELETE RESTRICT,"type" TEXT NOT NULL,"provider" TEXT NOT NULL DEFAULT 'local-demo',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
